def range_updates(n, votes): 
  diff = [0] * n
  for l, r, v in votes:
    diff[l] += v
    if r + 1 < n:
      diff[r + 1] -= v

  # Recipe 1.
  prefix_sum = [0] * n
  prefix_sum[0] = diff[0]
  for i in range(1, n):
    prefix_sum[i] = prefix_sum[i - 1] + diff[i]
  return prefix_sum

