function rangeUpdates(n, votes) {
  const diff = new Array(n).fill(0);
  for (const [l, r, v] of votes) {
    diff[l] += v;
    if (r + 1 < n) {
      diff[r + 1] -= v;
    }
  }

  // Recipe 1.
  const prefixSum = new Array(n).fill(0);
  prefixSum[0] = diff[0];
  for (let i = 1; i < n; i++) {
    prefixSum[i] = prefixSum[i - 1] + diff[i];
  }
  return prefixSum;
}

