class RangeUpdates {
  public int[] solve(int n, int[][] votes) {
    int[] diff = new int[n];
    for (int[] vote : votes) {
      int l = vote[0], r = vote[1], v = vote[2];
      diff[l] += v;
      if (r + 1 < n) {
        diff[r + 1] -= v;
      }
    }

    // Recipe 1.
    int[] prefixSum = new int[n];
    prefixSum[0] = diff[0];
    for (int i = 1; i < n; i++) {
      prefixSum[i] = prefixSum[i - 1] + diff[i];
    }
    return prefixSum;
  }
}

